def resolve(path, cwd, links):
    if path.startswith('/'):
        current = '/'
        components = path.split('/')[1:]
    else:
        current = cwd
        components = path.split('/')

    link_count = 0
    max_links = 8

    i = 0
    while i < len(components):
        component = components[i]

        if component == '' or component == '.':
            i += 1
            continue

        if component == '..':
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if not current:
                    current = '/'
            i += 1
            continue

        if current == '/':
            next_path = '/' + component
        else:
            next_path = current + '/' + component

        if next_path in links:
            link_count += 1
            if link_count > max_links:
                return None

            target = links[next_path]

            if target.startswith('/'):
                current = '/'
                target_components = target.split('/')[1:]
            else:
                current = next_path.rsplit('/', 1)[0]
                if not current:
                    current = '/'
                target_components = target.split('/')

            remaining_components = components[i+1:]
            components = target_components + remaining_components
            i = 0
        else:
            current = next_path
            i += 1

    if current == '/':
        return '/'
    return current

